  'legal.eyebrow': 'Informação legal',
  'legal.pilotNotice': 'Versão provisória para o piloto. A identificação jurídica final do responsável pelo tratamento deve ser confirmada antes da abertura pública/comercial.',
  'legal.updated': 'Atualizado em 1 de outubro de 2026',
