  'communities.speedSkating.placedHeatHint': 'Regista uma manga de cada vez. Identifica a série no nome da jornada, seleciona entre 2 e 6 atletas (até 4 nas finais) e confirma uma posição de chegada única para cada atleta. Os tempos são opcionais. As posições e os dois primeiros das mangas anteriores às finais são apenas registos provisórios do organizador: não há apuramento, transição entre fases ou classificação federativa automáticos. As exceções e decisões dos juízes têm de ser tratadas separadamente.',
