  'adminVenueGps.rodoviaNumberingWarning': "Existe uma fotografia partilhada por visitantes de uma placa com a distribuição numerada dos campos. É um esquema sem georreferenciação e a data da placa não foi confirmada. A AF Braga confirma o Campo n.º 1 (105 × 68 m) na época 2025/2026, mas não o respetivo GPS. Não converter a planta em coordenadas nem assumir que os números correspondem a polígonos OSM.",
  'adminVenueGps.rodoviaNumberingSign': "Ver fotografia da placa na galeria",
  'adminVenueGps.rodoviaFieldOneSchedule': "AF Braga: Campo n.º 1 (2025/2026)",
  'adminVenueGps.rodoviaTreePointWarning': "A Câmara publicou coordenadas neste parque num relatório de janeiro de 2025, mas pertencem a uma árvore inspecionada, não a qualquer campo. Nunca copiar esse ponto para um recinto. O GeoPortal municipal pode ajudar na investigação; os campos ainda precisam de identificação individual.",
  'adminVenueGps.rodoviaTreePointReport': "Relatório municipal: GPS da árvore (não do campo)",
  'adminVenueGps.rodoviaOfficialGeoportal': "Consultar GeoPortal oficial de Braga",
  'adminVenueGps.rodoviaMapTitle': "Rodovia — o parque e o edifício não são os campos numerados",
  'adminVenueGps.rodoviaMapCaution': "O roteiro municipal distingue o parque desportivo do complexo contíguo. As áreas OSM identificam um parque e um edifício, não um campo numerado nem a sua entrada. Não copiar os respetivos pontos GPS. O guia é histórico, pelo que as quantidades de campos podem ter mudado.",
  'adminVenueGps.rodoviaMunicipalGuide': "Roteiro municipal com os dois espaços",
  'adminVenueGps.rodoviaParkArea': "OSM: área do Parque da Rodovia",
  'adminVenueGps.rodoviaBuildingArea': "OSM: edifício do Complexo da Rodovia",
  'adminVenueGps.contextBraga': "Braga: a Câmara Municipal identifica este campo pelo número dentro da Rodovia e documenta outro campo numerado na mesma morada. Confirmar qual é a superfície antes de propor GPS; não os fundir nem reutilizar um ponto genérico.",
  'adminVenueGps.contextMira': "Mira: o campo de padel do Fojo é distinto do campo de futebol 11 no mesmo complexo. Não utilizar coordenadas do campo de futebol.",
  'adminVenueGps.contextWarning': "Fontes documentais sem coordenadas para este recinto. Não é candidato GPS nem autorização para alterar morada ou fundir fichas.",
  'adminVenueGps.contextPrimary': "Fonte oficial do recinto",
  'adminVenueGps.contextRelated': "Fonte oficial para distinguir instalações",
  'adminVenueGps.showInvestigated': "Ver casos investigados",
  'adminVenueGps.showAll': "Mostrar todos os recintos sem GPS",
  'adminVenueGps.noInvestigated': "Sem casos investigados pendentes neste distrito.",
  'adminVenueGps.review': "Propor alteração",
  'adminVenueGps.warning': "A morada e a referência são pistas de pesquisa, não comprovativos GPS. Nunca usar o centro de uma localidade ou complexo como se fosse o recinto. A publicação exige fonte HTTPS verificada e aprovação administrativa.",
