// The English dictionary stays out of the public Portuguese startup bundle.
// The initial English locale is preloaded in main.ts before Angular bootstraps,
// preserving synchronous appTranslate() calls across all existing components.
let englishDictionary: Dictionary | undefined;
let englishLoading: Promise<void> | undefined;

export function preloadEnglishTranslations(): Promise<void> {
  if (englishDictionary) {
    return Promise.resolve();
  }
  if (!englishLoading) {
    englishLoading = import('./translations-en')
      .then(module => {
        englishDictionary = module.EN;
      })
      .catch(error => {
        // Allow retry when a chunk request fails (e.g. temporary network error).
        englishLoading = undefined;
        throw error;
      });
  }
  return englishLoading;
}

export function prepareInitialTranslations(): Promise<void> {
  if (typeof localStorage === 'undefined' || localStorage.getItem('d24-language') !== 'en') {
    return Promise.resolve();
  }
  return preloadEnglishTranslations();
}


export function appTranslate(
  key: string,
  params?: Record<string, string | number>
): string {
  const language: AppLanguage =
    typeof localStorage !== 'undefined' && localStorage.getItem('d24-language') === 'en'
      ? 'en'
      : 'pt';
  const dictionary = language === 'en' ? (englishDictionary ?? PT) : PT;
  let value = dictionary[key] ?? PT[key] ?? key;

  for (const [name, replacement] of Object.entries(params ?? {})) {
    value = value.replaceAll('{{' + name + '}}', String(replacement));
  }

  return value;
}

@Injectable({ providedIn: 'root' })
export class I18nService {
  private readonly storageKey = 'd24-language';
  private language: AppLanguage = this.readInitialLanguage();
  private requestedLanguage: AppLanguage = this.language;

  constructor() {
    this.applyDocumentLanguage();
  }

  get currentLanguage(): AppLanguage {
    return this.language;
  }

  setLanguage(language: AppLanguage): void {
    this.requestedLanguage = language;
    if (language === 'en' && !englishDictionary) {
      // Do not show mixed PT/EN text while the English chunk is loading.
      void preloadEnglishTranslations()
        .then(() => {
          if (this.requestedLanguage === 'en') {
            this.activateLanguage('en');
          }
        })
        .catch(error => console.error('Could not load English translations.', error));
      return;
    }
    this.activateLanguage(language);
  }

  private activateLanguage(language: AppLanguage): void {
    this.language = language;
    localStorage.setItem(this.storageKey, language);
    this.applyDocumentLanguage();
  }

  translate(key: string, params?: Record<string, string | number>): string {
    const dictionary = this.language === 'en' ? (englishDictionary ?? PT) : PT;
    let value = dictionary[key] ?? PT[key] ?? key;

    for (const [name, replacement] of Object.entries(params ?? {})) {
      value = value.replaceAll('{{' + name + '}}', String(replacement));
    }

    return value;
  }

  private readInitialLanguage(): AppLanguage {
    const stored = localStorage.getItem(this.storageKey);
    return stored === 'en' ? 'en' : 'pt';
  }

  private applyDocumentLanguage(): void {
    document.documentElement.lang = this.language === 'en' ? 'en' : 'pt-PT';
  }
}
